import React, { useEffect, useRef, useState } from 'react';
import { ArrowUpRight, ExternalLink, Layers, X } from 'lucide-react';
import miniProjects from '../data/miniProjects';

const MiniProjects = ({ className = '' }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [selectedId, setSelectedId] = useState(miniProjects[0].id);
  const dialogRef = useRef(null);
  const triggerRef = useRef(null);
  const activeProject = miniProjects.find(project => project.id === selectedId);

  useEffect(() => {
    if (!isOpen) return;

    const dialog = dialogRef.current;
    const trigger = triggerRef.current;
    const previousOverflow = document.body.style.overflow;
    dialog.showModal();
    document.body.style.overflow = 'hidden';

    return () => {
      dialog.close();
      document.body.style.overflow = previousOverflow;
      trigger?.focus({ preventScroll: true });
    };
  }, [isOpen]);

  const dismiss = () => setIsOpen(false);

  return (
    <>
      <div
        className={`${className} card flex min-h-[28rem] flex-col items-center justify-center bg-gradient-to-br from-surface-800 to-primary-950/60 p-6 text-center`}
      >
        <div className='mb-5 flex h-16 w-16 items-center justify-center rounded-2xl border border-primary-500/30 bg-primary-500/10 text-primary-300'>
          <Layers size={28} aria-hidden='true' />
        </div>
        <p className='mb-3 text-xs uppercase tracking-[0.2em] text-primary-300'>
          The side projects
        </p>
        <h3 className='mb-3 text-xl font-bold'>Mini projects</h3>
        <p className='max-w-xs text-sm leading-relaxed text-gray-400'>
          Small builds, useful tools, and ideas brought to life.
        </p>
        <div className='mt-5 flex flex-wrap justify-center gap-2'>
          {miniProjects.map(project => (
            <span
              key={project.id}
              className='rounded border border-primary-500/20 bg-primary-600/10 px-2 py-1 text-xs font-medium text-primary-300'
            >
              {project.title}
            </span>
          ))}
        </div>
        <button
          ref={triggerRef}
          type='button'
          onClick={() => setIsOpen(true)}
          aria-haspopup='dialog'
          aria-controls='mini-projects-dialog'
          className='btn-primary mt-6 inline-flex items-center gap-2 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-primary-300'
        >
          Explore mini projects
          <ArrowUpRight size={18} aria-hidden='true' />
        </button>
      </div>

      {isOpen && (
        <dialog
          ref={dialogRef}
          id='mini-projects-dialog'
          aria-labelledby='mini-projects-title'
          aria-describedby='mini-projects-description'
          className='mini-projects-dialog rounded-2xl border border-surface-600 bg-surface-900 p-0 text-gray-100 shadow-2xl backdrop:bg-black/75 backdrop:backdrop-blur-sm'
          onCancel={event => {
            event.preventDefault();
            dismiss();
          }}
          onClose={dismiss}
          onClick={event => {
            if (event.target === event.currentTarget) dismiss();
          }}
        >
          <div>
            <div className='flex items-start justify-between gap-4 border-b border-surface-600 p-5 sm:p-6'>
              <div>
                <h2
                  id='mini-projects-title'
                  className='text-xl font-bold sm:text-2xl'
                >
                  Mini projects
                </h2>
                <p
                  id='mini-projects-description'
                  className='mt-1 text-sm text-gray-400'
                >
                  A little space for experiments. Pick a project and try it out.
                </p>
              </div>
              <button
                type='button'
                onClick={dismiss}
                aria-label='Close mini projects'
                className='btn-secondary shrink-0 p-2 focus-visible:outline focus-visible:outline-2 focus-visible:outline-primary-300'
              >
                <X size={20} aria-hidden='true' />
              </button>
            </div>

            <div className='flex flex-col lg:flex-row'>
              <nav
                aria-label='Mini projects'
                className='grid gap-2 border-b border-surface-600 p-4 sm:grid-cols-2 lg:w-64 lg:shrink-0 lg:grid-cols-1 lg:content-start lg:border-b-0 lg:border-r'
              >
                {miniProjects.map(project => (
                  <button
                    key={project.id}
                    type='button'
                    aria-pressed={project.id === selectedId}
                    onClick={() => setSelectedId(project.id)}
                    className={`rounded-xl border p-4 text-left transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-primary-300 ${
                      project.id === selectedId
                        ? 'border-primary-400/60 bg-primary-600/20'
                        : 'border-transparent bg-surface-800 hover:border-surface-500'
                    }`}
                  >
                    <span className='mb-1 block text-xs text-primary-300'>
                      {project.category}
                    </span>
                    <span className='block text-sm font-semibold'>
                      {project.title}
                    </span>
                  </button>
                ))}
              </nav>

              <div className='min-w-0 flex-1 p-4 sm:p-6'>
                <div className='mb-4 flex flex-wrap items-start justify-between gap-4'>
                  <div className='min-w-0 flex-1 basis-48'>
                    <h3 className='text-lg font-bold'>{activeProject.title}</h3>
                    <p className='mt-1 text-sm leading-relaxed text-gray-400'>
                      {activeProject.description}
                    </p>
                  </div>
                  <a
                    href={activeProject.url}
                    target='_blank'
                    rel='noopener noreferrer'
                    className='btn-primary inline-flex shrink-0 items-center gap-2 text-sm focus-visible:outline focus-visible:outline-2 focus-visible:outline-primary-300'
                  >
                    Open project
                    <ExternalLink size={16} aria-hidden='true' />
                    <span className='sr-only'> (opens in a new tab)</span>
                  </a>
                </div>

                <div className='overflow-hidden rounded-xl border border-surface-600 bg-surface-800'>
                  <div className='flex items-center gap-2 border-b border-surface-600 px-4 py-3 text-xs text-gray-400'>
                    <span
                      className='h-2 w-2 shrink-0 rounded-full bg-primary-400'
                      aria-hidden='true'
                    />
                    <span className='shrink-0'>Live preview</span>
                    <span className='ml-auto truncate'>
                      {new URL(activeProject.url).hostname}
                    </span>
                  </div>
                  <iframe
                    key={activeProject.id}
                    title={`${activeProject.title} live preview`}
                    src={activeProject.url}
                    className='mini-project-preview block w-full border-0 bg-white'
                    sandbox='allow-scripts allow-same-origin allow-forms allow-popups allow-popups-to-escape-sandbox allow-downloads'
                    referrerPolicy='no-referrer'
                  />
                </div>
                <p className='mt-3 text-xs leading-relaxed text-gray-400'>
                  For the full experience, or if the preview doesn&apos;t load,{' '}
                  <a
                    href={activeProject.url}
                    target='_blank'
                    rel='noopener noreferrer'
                    className='text-primary-300 underline underline-offset-2 hover:text-primary-200'
                  >
                    open {activeProject.title} in a new tab
                  </a>
                  .
                </p>
              </div>
            </div>
          </div>
        </dialog>
      )}
    </>
  );
};

export default MiniProjects;
